[metadata] {"type": "create", "filePath": "/workspace/repo/src/integrations/prefect-kubernetes/prefect_kubernetes/diagnostics.py", "content": """"Structured diagnosis of Kubernetes pod failures.

This module inspects a pod's status dictionary (as reported by the Kubernetes
API) and, for known failure conditions, produces a structured
:class:`InfrastructureDiagnosis` describing what went wrong and how to resolve
it. Healthy pods, or pods in states that don't require intervention, produce no
diagnosis.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any


class DiagnosisLevel(str, Enum):
    """Severity level for an infrastructure diagnosis."""

    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True)
class InfrastructureDiagnosis:
    """A structured diagnosis of a Kubernetes pod failure.

    Instances are immutable (frozen) so that a diagnosis can be safely cached
    and compared. Two diagnoses with identical field values compare as equal.
    """

    level: DiagnosisLevel
    summary: str
    detail: str
    resolution: str


def _detail(reason: str, message: str | None) -> str:
    """Build a detail string, always including the reason and any message."""
    if message:
        return f"{reason}: {message}"
    return reason


def _iter_container_statuses(status: dict[str, Any]) -> list[dict[str, Any]]:
    """Yield init and regular container statuses, init containers first."""
    containers: list[dict[str, Any]] = []
    for key in ("initContainerStatuses", "containerStatuses"):
        value = status.get(key)
        if value:
            containers.extend(value)
    return containers


def _diagnose_waiting(containers: list[dict[str, Any]]) -> InfrastructureDiagnosis | None:
    """Diagnose failures reported via a container's ``waiting`` state."""
    for container in containers:
        waiting = container.get("state", {}).get("waiting")
        if not waiting:
            continue
        reason = waiting.get("reason")
        message = waiting.get("message")
        name = container.get("name", "<unknown>")

        if reason in ("ImagePullBackOff", "ErrImagePull"):
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=f"Container '{name}' failed to pull its image",
                detail=_detail(reason, message),
                resolution=(
                    "Verify the image name and tag are correct, the image exists in "
                    "the registry, and that valid image pull credentials are configured."
                ),
            )
        if reason == "CrashLoopBackOff":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=f"Container '{name}' is crash-looping",
                detail=_detail(reason, message),
                resolution=(
                    "Inspect the container logs to determine why the process is "
                    "exiting and address the underlying error."
                ),
            )
    return None


def _diagnose_terminated(
    containers: list[dict[str, Any]],
) -> InfrastructureDiagnosis | None:
    """Diagnose failures reported via a container's ``terminated`` state."""
    for container in containers:
        terminated = container.get("state", {}).get("terminated")
        if not terminated:
            continue
        reason = terminated.get("reason")
        message = terminated.get("message")
        name = container.get("name", "<unknown>")

        if reason == "OOMKilled":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.ERROR,
                summary=f"Container '{name}' was OOMKilled",
                detail=_detail(reason, message),
                resolution=(
                    "Increase the memory limit/request for the pod or reduce the "
                    "workload's memory usage."
                ),
            )
        if reason == "Evicted":
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary=f"Container '{name}' was evicted",
                detail=_detail(reason, message),
                resolution=(
                    "Check node resource pressure and pod resource requests; the pod "
                    "may need to be rescheduled onto a node with more capacity."
                ),
            )
    return None


def _diagnose_pod_evicted(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Diagnose a pod-level eviction reported on the status itself."""
    if status.get("reason") != "Evicted":
        return None
    message = status.get("message")
    return InfrastructureDiagnosis(
        level=DiagnosisLevel.WARNING,
        summary="Pod was evicted from its node",
        detail=message or "Evicted",
        resolution=(
            "Check node resource pressure and pod resource requests; the pod may "
            "need to be rescheduled onto a node with more capacity."
        ),
    )


def _diagnose_unschedulable(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Diagnose an unschedulable pod reported via its ``PodScheduled`` condition."""
    for condition in status.get("conditions", []):
        if (
            condition.get("type") == "PodScheduled"
            and condition.get("reason") == "Unschedulable"
        ):
            message = condition.get("message")
            return InfrastructureDiagnosis(
                level=DiagnosisLevel.WARNING,
                summary="Pod is unschedulable",
                detail=message or "Unschedulable",
                resolution=(
                    "Check that the cluster has nodes with sufficient resources and "
                    "that node selectors, affinities, and tolerations can be satisfied."
                ),
            )
    return None


def diagnose_k8s_pod(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Inspect a pod status dictionary and return a structured diagnosis.

    Args:
        status: The ``status`` section of a Kubernetes pod object.

    Returns:
        An :class:`InfrastructureDiagnosis` for known failure conditions, or
        ``None`` if the pod is healthy or in a state not requiring intervention.
    """
    if not status:
        return None

    containers = _iter_container_statuses(status)

    # Waiting-state failures take priority over terminated-state failures so
    # that, for example, an image pull failure is surfaced ahead of a sibling
    # container that was OOMKilled.
    if diagnosis := _diagnose_waiting(containers):
        return diagnosis
    if diagnosis := _diagnose_terminated(containers):
        return diagnosis
    if diagnosis := _diagnose_pod_evicted(status):
        return diagnosis
    if diagnosis := _diagnose_unschedulable(status):
        return diagnosis

    return None
